-- 0074 · The medicines list (RHIA, June 2026) and one pharmacy place per visit.
--
-- 1. The RHIA reimbursable medicines list of June 2026 (assets/RHIA REIMBURSABLE MEDICINES LIST
--    JUNE-2026.xlsx): 1446 medicines with their code, generic name, presentation (brand,
--    form, strength), prescribing rule (DT = dentist only, PED, GYN…), selling unit and price.
--    They join the medicines catalogue at quantity 0: what the pharmacy really holds is received
--    with its batch and expiry (Stock → Receive). A medicine already in the catalogue under the
--    same code is left as it is; the tariff becomes the cash price only where none is set.
-- 2. "Finish visit" closed every place of the visit, then opened a new pharmacy place, so a
--    patient the doctor had already sent to the pharmacy showed the pharmacy twice. The open
--    pharmacy (or cashier) place is now kept.

alter table item add column if not exists atc_group text;
alter table item add column if not exists prescribing_rule text;
alter table item add column if not exists source text;

insert into item (code, name_generic, name_brand, strength, unit, selling_unit, prescribing_rule, atc_group, source, active)
select v.code, v.generic, v.designation, v.designation, initcap(lower(v.unit)), initcap(lower(v.unit)), v.instr, v.grp,
       'RHIA June 2026', true
